// userDataSchema mirrors the widely shared Kylo "userdata*.avro" samples: a
// flat Kite-inferred record with nullable long/double unions.
const userDataSchema = `{
  "type":"record","name":"kylosample","doc":"Schema generated by Kite",
  "fields":[
    {"name":"registration_dttm","type":"string"},
    {"name":"id","type":"long"},
    {"name":"email","type":"string"},
    {"name":"cc","type":["null","long"],"default":null},
    {"name":"salary","type":["null","double"],"default":null},
    {"name":"comments","type":"string"}
  ]
}`

func writeOCF(t *testing.T, schema string, records ...any) []byte {
	t.Helper()
	var buf bytes.Buffer
	enc, err := ocf.NewEncoder(schema, &buf)
	if err != nil {
		t.Fatalf("NewEncoder: %v", err)
	}
	for _, record := range records {
		if err := enc.Encode(record); err != nil {
			t.Fatalf("Encode: %v", err)
		}
	}
	if err := enc.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	return buf.Bytes()
}

// A non-Capture Avro file used to import as empty produce actions, because the
// importer only read the EventData Body field. Each record must instead become
// the event body, byte-exact: schema field order, no HTML escaping, exact longs.
func TestConvertAvroRecordsImportsEachRecordAsJSONBody(t *testing.T) {
	const comments = "<script>alert('hi')</script> & \ufeff\u202etest\u202e 👩🏽 \u2029"
	data := writeOCF(t, userDataSchema,
		map[string]any{"registration_dttm": "2016-02-03T13:36:39Z", "id": int64(1), "email": "dlewis0@clickbank.net", "cc": nil, "salary": 140249.37, "comments": ""},
		// 4017953398128713005 > 2^53: a float64 hop would corrupt it.
		map[string]any{"registration_dttm": "2016-02-03T18:29:04Z", "id": int64(3), "email": "m@example.jp", "cc": int64(4017953398128713005), "salary": nil, "comments": comments},
	)

	res, err := Convert(ConvertRequest{Name: "userdata", Data: data})
	if err != nil {
		t.Fatalf("Convert: %v", err)
	}
	if res.Stats.SourceFormat != SourceFormatAvroRecords || res.Stats.AvroSchema != "kylosample" {
		t.Fatalf("stats = %+v, want avro_records/kylosample", res.Stats)
	}
	if res.Stats.RecordsRead != 2 || res.Stats.ActionsEmitted != 2 || res.Stats.EmptyBodies != 0 || res.Stats.PartitionKeys != 0 {
		t.Fatalf("unexpected stats: %+v", res.Stats)
	}
	if !hasWarningContaining(res.Warnings, `Avro schema "kylosample" is not the Event Hubs Capture EventData schema`) {
		t.Fatalf("expected a non-Capture schema warning, got %v", res.Warnings)
	}
	if hasWarningContaining(res.Warnings, "empty body") {
		t.Fatalf("records must not import as empty bodies: %v", res.Warnings)
	}
	want := []string{
		`{"registration_dttm":"2016-02-03T13:36:39Z","id":1,"email":"dlewis0@clickbank.net","cc":null,"salary":140249.37,"comments":""}`,
		`{"registration_dttm":"2016-02-03T18:29:04Z","id":3,"email":"m@example.jp","cc":4017953398128713005,"salary":null,"comments":"<script>alert('hi')</script> & ` + "\ufeff\u202etest\u202e 👩🏽 " + `\u2029"}`,
	}
	for i, action := range res.Script.Actions {
		if action.Type != "eventhubs_produce" || action.BodyEncoding != "" {
			t.Fatalf("action %d = %+v", i, action)
		}
		if action.Body != want[i] {
			t.Fatalf("action %d body:\n got %s\nwant %s", i, action.Body, want[i])
		}
		if len(action.Assertions) != 1 || action.Assertions[0].Type != "message_received" {
			t.Fatalf("action %d assertions = %+v", i, action.Assertions)
		}
		if action.Metadata["source_record_index"] != i+1 || action.Metadata["avro_schema"] != "kylosample" {
			t.Fatalf("action %d metadata = %#v", i, action.Metadata)
		}
		if _, ok := action.Params["partition_key"]; ok {
			t.Fatalf("action %d invented a partition key", i)
		}
	}
	if !res.Script.Config.EventHubs.Mock || res.Script.Protocol != "eventhubs" {
		t.Fatalf("script = %+v", res.Script)
	}
}

func TestConvertAvroRecordsRendersEveryAvroType(t *testing.T) {
	const schema = `{
	  "type":"record","name":"Order","namespace":"com.example",
	  "fields":[
	    {"name":"ok","type":"boolean"},
	    {"name":"qty","type":"int"},
	    {"name":"ratio","type":"float"},
	    {"name":"nan","type":"double"},
	    {"name":"status","type":{"type":"enum","name":"Status","symbols":["NEW","PAID"]}},
	    {"name":"tags","type":{"type":"array","items":"string"}},
	    {"name":"attrs","type":{"type":"map","values":"long"}},
	    {"name":"choice","type":["null","string","long"]},
	    {"name":"choice_null","type":["null","string","long"]},
	    {"name":"line","type":{"type":"record","name":"Line","fields":[{"name":"sku","type":"string"}]}},
	    {"name":"maybe_line","type":["null","Line"]},
	    {"name":"raw","type":"bytes"},
	    {"name":"hash","type":{"type":"fixed","name":"Hash","size":4}},
	    {"name":"price","type":{"type":"bytes","logicalType":"decimal","precision":9,"scale":2}},
	    {"name":"day","type":{"type":"int","logicalType":"date"}},
	    {"name":"at_ms","type":{"type":"long","logicalType":"timestamp-millis"}},
	    {"name":"at_us","type":{"type":"long","logicalType":"timestamp-micros"}},
	    {"name":"tod_ms","type":{"type":"int","logicalType":"time-millis"}},
	    {"name":"tod_us","type":{"type":"long","logicalType":"time-micros"}},
	    {"name":"uid","type":{"type":"string","logicalType":"uuid"}},
	    {"name":"span","type":{"type":"fixed","name":"Span","size":12,"logicalType":"duration"}}
	  ]
	}`
	at := time.Date(2026, 6, 21, 12, 30, 0, 123456000, time.UTC)
	record := map[string]any{
		"ok":          true,
		"qty":         7,
		"ratio":       float32(0.1),
		"nan":         math.NaN(),
		"status":      "PAID",
		"tags":        []any{"a", "<b>"},
		"attrs":       map[string]any{"z": int64(2), "a": int64(1)},
		"choice":      map[string]any{"long": int64(42)},
		"choice_null": nil,
		"line":        map[string]any{"sku": "SKU-1"},
		"maybe_line":  map[string]any{"com.example.Line": map[string]any{"sku": "SKU-2"}},
		"raw":         []byte{0xff, 0x00},
		"hash":        [4]byte{0xde, 0xad, 0xbe, 0xef},
		"price":       big.NewRat(123456, 100),
		"day":         time.Date(2026, 6, 21, 0, 0, 0, 0, time.UTC),
		"at_ms":       at,
		"at_us":       at,
		"tod_ms":      90 * time.Minute,
		"tod_us":      1500 * time.Microsecond,
		"uid":         "c0ffee00-0000-4000-8000-000000000001",
		"span":        avro.LogicalDuration{Months: 1, Days: 2, Milliseconds: 3},
	}
	res, err := Convert(ConvertRequest{Data: writeOCF(t, schema, record)})
	if err != nil {
		t.Fatalf("Convert: %v", err)
	}
	if res.Stats.AvroSchema != "com.example.Order" {
		t.Fatalf("schema name = %q", res.Stats.AvroSchema)
	}
	want := `{"ok":true,"qty":7,"ratio":0.1,"nan":"NaN","status":"PAID","tags":["a","<b>"],"attrs":{"a":1,"z":2},` +
		`"choice":42,"choice_null":null,"line":{"sku":"SKU-1"},"maybe_line":{"sku":"SKU-2"},` +
		`"raw":"/wA=","hash":"3q2+7w==","price":1234.56,"day":20625,` +
		`"at_ms":1782045000123,"at_us":1782045000123456,"tod_ms":5400000,"tod_us":1500,` +
		`"uid":"c0ffee00-0000-4000-8000-000000000001","span":{"months":1,"days":2,"milliseconds":3}}`
	if got := res.Script.Actions[0].Body; got != want {
		t.Fatalf("body:\n got %s\nwant %s", got, want)
	}
	for _, warning := range []string{"2 bytes/fixed field value(s) were rendered as base64", "1 NaN/Infinity float value(s)"} {
		if !hasWarningContaining(res.Warnings, warning) {
			t.Fatalf("missing warning %q in %v", warning, res.Warnings)
		}
	}
}

func TestConvertAvroRecordsStringAndBytesSchemasAreVerbatimBodies(t *testing.T) {
	res, err := Convert(ConvertRequest{Data: writeOCF(t, `"string"`, `{"deviceId":"d-1"}`, "plain <text>")})
	if err != nil {
		t.Fatalf("Convert string: %v", err)
	}
	if got := []string{res.Script.Actions[0].Body, res.Script.Actions[1].Body}; got[0] != `{"deviceId":"d-1"}` || got[1] != "plain <text>" {
		t.Fatalf("string bodies = %q", got)
	}

	binary := []byte{0xff, 0xfe, 0x00, 0x01}
	res, err = Convert(ConvertRequest{Data: writeOCF(t, `"bytes"`, binary, []byte{})})
	if err != nil {
		t.Fatalf("Convert bytes: %v", err)
	}
	first := res.Script.Actions[0]
	if first.BodyEncoding != "base64" || first.Body != base64.StdEncoding.EncodeToString(binary) || res.Stats.BinaryBodies != 1 {
		t.Fatalf("binary record = %+v stats=%+v", first, res.Stats)
	}
	if empty := res.Script.Actions[1]; empty.Body != "" || len(empty.Assertions) != 0 || res.Stats.EmptyBodies != 1 {
		t.Fatalf("empty record = %+v stats=%+v", empty, res.Stats)
	}
}

// A nullable payload union (or enum) is still the payload: a file of raw
// messages written as ["null","bytes"] must not become quoted base64 JSON.
func TestConvertAvroRecordsTopLevelUnionAndEnumAreVerbatimBodies(t *testing.T) {
	binary := []byte{0xff, 0x01}
	res, err := Convert(ConvertRequest{Data: writeOCF(t, `["null","bytes"]`, nil, binary, []byte(`{"a":1}`))})
	if err != nil {
		t.Fatalf("Convert bytes union: %v", err)
	}
	actions := res.Script.Actions
	if actions[0].Body != "" || actions[1].BodyEncoding != "base64" || actions[1].Body != base64.StdEncoding.EncodeToString(binary) || actions[2].Body != `{"a":1}` {
		t.Fatalf("bytes union bodies = %+v", actions)
	}
	if !hasWarningContaining(res.Warnings, "string and bytes values are the body") {
		t.Fatalf("union body description missing: %v", res.Warnings)
	}

	res, err = Convert(ConvertRequest{Data: writeOCF(t, `["null","string"]`, "plain <text>")})
	if err != nil || res.Script.Actions[0].Body != "plain <text>" {
		t.Fatalf("string union body = %+v, err %v", res, err)
	}
	res, err = Convert(ConvertRequest{Data: writeOCF(t, `{"type":"enum","name":"Status","symbols":["NEW","PAID"]}`, "PAID")})
	if err != nil || res.Script.Actions[0].Body != "PAID" {
		t.Fatalf("enum body = %+v, err %v", res, err)
	}
}

// Only the EventData envelope selects Capture decoding, which reads nothing
// but Body and the envelope fields; any other field means a plain data record.
func TestConvertCaptureDetectionNeedsTheEnvelope(t *testing.T) {
	for _, tc := range []struct {
		name, schema string
		record       map[string]any
		want         string
	}{
		{"body only", `{"type":"record","name":"Email","fields":[{"name":"Subject","type":"string"},{"name":"Body","type":"string"}]}`, map[string]any{"Subject": "hi", "Body": "text"}, `{"Subject":"hi","Body":"text"}`},
		{"body and one envelope name", `{"type":"record","name":"Doc","fields":[{"name":"Subject","type":"string"},{"name":"Body","type":"string"},{"name":"Properties","type":{"type":"map","values":"string"}}]}`, map[string]any{"Subject": "hi", "Body": "text", "Properties": map[string]any{"k": "v"}}, `{"Subject":"hi","Body":"text","Properties":{"k":"v"}}`},
	} {
		res, err := Convert(ConvertRequest{Data: writeOCF(t, tc.schema, tc.record)})
		if err != nil {
			t.Fatalf("%s: Convert: %v", tc.name, err)
		}
		if res.Stats.SourceFormat != SourceFormatAvroRecords || res.Script.Actions[0].Body != tc.want {
			t.Fatalf("%s: stats=%+v body=%q", tc.name, res.Stats, res.Script.Actions[0].Body)
		}
	}

	capture, err := Convert(ConvertRequest{Data: writeCapture(t, []map[string]any{captureRecord(1, "k", "s", "payload")})})
	if err != nil {
		t.Fatalf("Convert capture: %v", err)
	}
	if capture.Stats.SourceFormat != SourceFormatCapture || capture.Stats.AvroSchema != "Microsoft.ServiceBus.Messaging.EventData" {
		t.Fatalf("capture stats = %+v", capture.Stats)
	}
	if hasWarningContaining(capture.Warnings, "not the Event Hubs Capture EventData schema") {
		t.Fatalf("capture file flagged as non-Capture: %v", capture.Warnings)
	}
}

func TestConvertAvroRecordsMaxEventsCap(t *testing.T) {
	var records []any
	for i := range 5 {
		records = append(records, map[string]any{"registration_dttm": "t", "id": int64(i), "email": "e", "cc": nil, "salary": nil, "comments": ""})
	}
	res, err := Convert(ConvertRequest{Data: writeOCF(t, userDataSchema, records...), MaxEvents: 2})
	if err != nil {
		t.Fatalf("Convert: %v", err)
	}
	if res.Stats.RecordsRead != 5 || len(res.Script.Actions) != 2 || !hasWarningContaining(res.Warnings, "raise max_events") {
		t.Fatalf("stats=%+v warnings=%v", res.Stats, res.Warnings)
	}
	if !strings.Contains(res.Summary, `Imported 2 of 5 Avro "kylosample" records`) {
		t.Fatalf("summary = %q", res.Summary)
	}
}
